    private readonly MarketFixture fixture=new();public Task InitializeAsync()=>fixture.InitializeAsync();public Task DisposeAsync()=>fixture.DisposeAsync();
    private static string Id()=>Guid.NewGuid().ToString("N");private static string V(JsonNode x,string key)=>CreditCheckoutQuoteQa.Text(x,key);private static async Task<JsonNode> Read(HttpResponseMessage r){using(r){var raw=await r.Content.ReadAsStringAsync();Assert.True(r.IsSuccessStatusCode,$"HTTP{(int)r.StatusCode}: {raw}");var path=r.RequestMessage!.RequestUri!.PathAndQuery;if(Environment.GetEnvironmentVariable("SHOP_CREDIT_CLEARANCE_WIRE_DIR")is{Length:>0}dir&&(path.Contains("/clearance",StringComparison.Ordinal))){Assert.Contains("no-store",r.Headers.CacheControl!.ToString());Assert.Contains("noindex",r.Headers.GetValues("X-Robots-Tag").Single());Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)r.StatusCode,method=r.RequestMessage.Method.Method,path}));}return JsonNode.Parse(raw)!;}}
    [Theory][InlineData(true)][InlineData(false)]
    public async Task IndependentFinancialClearanceCommitsExactAcceptedAndMixedStockWithoutChangingScopeOrPrices(bool ordinary)
    {
        var helper=new SourcingConversionHttpSqlTests(fixture);var x=await helper.CreditQuoteMixedCart(ordinary);var s=x.Scenario;using var customer=s.Customer;using var finance=await fixture.ReuseStaff("FinanceManager");using var auth=new CreditQuoteReviewerAuth(fixture.Sql);using var reviewer=await auth.Client();
        await using(var scope=fixture.Sql.Factory.Services.CreateAsyncScope()){var sp=scope.ServiceProvider;var sales=sp.GetRequiredService<SalesDbContext>();Assert.StartsWith("SaymanTest_",sales.Database.GetDbConnection().Database);await using var tx=await sales.Database.BeginTransactionAsync(IsolationLevel.Serializable);var policy=await sales.ChargePolicies.AsNoTracking().SingleOrDefaultAsync();await sp.GetRequiredService<CheckoutChargePolicyService>().SaveAsync(new("flat","ارسال ساختگی","Synthetic QA","D21 QA only","D21 QA only","12345",null,"exempt",null,"goods","half_up",policy is null?null:Convert.ToBase64String(policy.Version)),default);var settings=await sales.OrderSettings.AsNoTracking().SingleOrDefaultAsync();await sp.GetRequiredService<CheckoutOrderSettingsService>().SaveAsync(new(true,60,2,settings is null?null:Convert.ToBase64String(settings.Version),true),default);await tx.CommitAsync();var stock=await sp.GetRequiredService<InventoryDbContext>().Stock.AsNoTracking().SingleAsync(v=>v.VariantId==s.Variant);Assert.Equal(2,stock.SourcingReserved);Assert.Equal(0,stock.Reserved);Assert.Equal(ordinary?3:2,stock.OnHand);}
        var current=await Read(await finance.GetAsync("/api/admin/credit/review-hold-policy"));var configured=await Read(await finance.PostAsJsonAsync("/api/admin/credit/review-hold-policy/commands/"+Id(),new ChequeReviewHoldInput("Enable",current["version"]?.GetValue<string>(),60,true)));var policyVersion=V(configured["policy"]!,"version");
        var scopeResult=await CreditCheckoutQuoteQa.Scope(customer,finance,reviewer,x.Plan,x.Version,"900719925474099300","InstallmentsTotalRial");var quote=(await Read(await customer.PostAsJsonAsync(CreditCheckoutQuoteQa.Route(Id()),CreditCheckoutQuoteQa.Input(scopeResult,V(x.Cart,"version"),x.Method,x.Plan))))["quote"]!;Assert.NotNull(quote["acceptedQuote"]);var command=Id();var input=new CreditOrderInput(V(quote,"id"),V(quote,"fingerprint"),"Synthetic accepted cheque QA","09100000000",new("IR","تهران","تهران","نشانی کاملاً ساختگی برای آزمون سفارش توافقی","1234567890"),"Software QA only",true,true,policyVersion);var first=await Read(await customer.PostAsJsonAsync("/api/credit-orders/commands/"+command,input));var order=first["order"]!;var id=V(order["summary"]!,"id");Assert.Equal(2,order["originalSnapshotVersion"]!.GetValue<int>());Assert.Equal(ordinary?2:1,order["lines"]!.AsArray().Count);Assert.Equal("9007199254740993",V(Assert.Single(order["lines"]!.AsArray(),l=>V(l!,"lineKind")=="acceptedOffer")!,"unitPriceRial"));Assert.False(order["canPay"]!.GetValue<bool>());
        Assert.Equal(policyVersion,V(first["reviewHold"]!,"policyVersion"));var deadline=order["summary"]!["expiresAt"]!.GetValue<DateTimeOffset>();foreach(var line in quote["acceptedQuote"]!["lines"]!.AsArray())if(line!["accepted"]is{}accepted){Assert.True(deadline<=accepted["purchaseUntil"]!.GetValue<DateTimeOffset>());Assert.True(deadline<=accepted["allocationExpiresAt"]!.GetValue<DateTimeOffset>());}
        await using(var scope=fixture.Sql.Factory.Services.CreateAsyncScope()){var sp=scope.ServiceProvider;var sales=sp.GetRequiredService<SalesDbContext>();var inv=sp.GetRequiredService<InventoryDbContext>();var stock=await inv.Stock.AsNoTracking().SingleAsync(v=>v.VariantId==s.Variant);Assert.Equal(ordinary?3:2,stock.Reserved);Assert.Equal(0,stock.SourcingReserved);Assert.Equal(ordinary?3:2,stock.OnHand);var hold=await inv.Reservations.SingleAsync(r=>r.OrderId==id);Assert.Equal(2,hold.ContractVersion);Assert.Equal(order["summary"]!["expiresAt"]!.GetValue<DateTimeOffset>(),hold.ExpiresAt);var agreement=await sales.SourcingPriceAgreements.SingleAsync(a=>a.AcceptanceId==s.Acceptance);Assert.Equal("Consumed",agreement.State);Assert.Equal(id,agreement.ConsumedOrderId);var allocation=await inv.SourcingAllocations.SingleAsync(a=>a.AcceptanceId==s.Acceptance);Assert.Equal("Transferred",allocation.State);Assert.Single(await sales.OrderOutbox.Where(e=>e.OrderId==id).ToArrayAsync());Assert.Single(await sp.GetRequiredService<CreditDbContext>().PurchaseScopeUses.Where(u=>u.OrderId==id).ToArrayAsync());}

        var financeBase="/api/admin/credit/orders/"+s.Owner.ToUpperInvariant()+"/"+id;var orderVersion=V(order["summary"]!,"version");var anchor=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Asia/Tehran")).DateTime).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);var preview=await Read(await finance.PostAsJsonAsync(financeBase+"/schedule/preview",new CreditSchedulePreviewInput(orderVersion,null,"Gregorian",anchor)));var schedule=(await Read(await finance.PostAsJsonAsync(financeBase+"/schedule/commands/"+Id(),new SaveCreditScheduleInput(orderVersion,null,"Gregorian",anchor,V(preview,"fingerprint"),true))))["revision"]!;var up=await Read(await finance.GetAsync(financeBase+"/upfront"));var required=V(up,"requiredAmountRial");await Read(await finance.PostAsJsonAsync(financeBase+"/upfront/commands/"+Id(),new CreditUpfrontInput(required=="0"?"ConfirmNoUpfrontDue":"ConfirmReceipt",orderVersion,V(schedule,"version"),null,required=="0"?"":"SYNTHETIC-NOT-BANK","Synthetic financial prerequisites only",DateTimeOffset.UtcNow,true)));
        foreach(var line in schedule["calculation"]!["lines"]!.AsArray()){var cheque=(await Read(await finance.PostAsJsonAsync(financeBase+"/cheques/receive/commands/"+Id(),new ReceiveChequeInput(orderVersion,V(schedule,"version"),line!["sequence"]!.GetValue<int>(),"SYNTHETIC-ACCEPTED-CHEQUE","No actual instrument",DateTimeOffset.UtcNow,true))))["cheque"]!;await Read(await finance.PostAsJsonAsync(financeBase+"/cheque-approvals/"+V(cheque,"id")+"/commands/"+Id(),new ChequeApprovalInput("Approve",orderVersion,V(schedule,"version"),V(cheque,"version"),null,"Synthetic manual approval only",DateTimeOffset.UtcNow,true,false)));}
        var clearance=financeBase+"/clearance";var ready=await Read(await finance.GetAsync(clearance));Assert.True(ready["canApprove"]!.GetValue<bool>());var financialCommand=Id();var financialInput=new CreditClearanceInput("Approve",V(ready,"orderVersion"),null,V(ready,"previewFingerprint"),"Synthetic accepted-line financial authority",true);var committed=await Read(await finance.PostAsJsonAsync(clearance+"/commands/"+financialCommand,financialInput));Assert.True(committed["initialCommit"]!.GetValue<bool>());var replay=await Read(await finance.PostAsJsonAsync(clearance+"/commands/"+financialCommand,financialInput));Assert.True(replay["replayed"]!.GetValue<bool>());await Read(await finance.GetAsync(clearance+"/commands/"+financialCommand));var approved=await Read(await finance.GetAsync(clearance));Assert.Equal("CreditApproved",V(approved,"orderState"));Assert.Equal("Allocated",V(approved,"reservationState"));Assert.True(approved["effective"]!.GetValue<bool>());await Read(await customer.GetAsync("/api/credit/orders/"+id+"/clearance"));
        var revoked=await Read(await finance.PostAsJsonAsync(clearance+"/commands/"+Id(),new CreditClearanceInput("Revoke",V(approved,"orderVersion"),V(approved["current"]!,"version"),V(approved,"previewFingerprint"),"Synthetic temporary authorization hold",true)));var paused=await Read(await finance.GetAsync(clearance));Assert.False(paused["effective"]!.GetValue<bool>());var refreshed=await Read(await finance.PostAsJsonAsync(clearance+"/commands/"+Id(),new CreditClearanceInput("Approve",V(paused,"orderVersion"),V(paused["current"]!,"version"),V(paused,"previewFingerprint"),"Synthetic reviewed financial authority",true)));Assert.False(refreshed["initialCommit"]!.GetValue<bool>());await Read(await finance.GetAsync(clearance+"/history"));
        var detail=await Read(await customer.GetAsync("/api/credit-orders/"+id));Assert.Equal(quote.ToJsonString(),detail["calculation"]!.ToJsonString());Assert.Equal(deadline,detail["order"]!["summary"]!["expiresAt"]!.GetValue<DateTimeOffset>());Assert.Equal(order["lines"]!.ToJsonString(),detail["order"]!["lines"]!.ToJsonString());using(var cancel=await customer.PostAsJsonAsync("/api/orders/v2/"+id+"/cancel",new{version=V(detail["order"]!["summary"]!,"version")}))Assert.Equal(System.Net.HttpStatusCode.Conflict,cancel.StatusCode);
        await using var final=fixture.Sql.Factory.Services.CreateAsyncScope();var finalSales=final.ServiceProvider.GetRequiredService<SalesDbContext>();var finalInv=final.ServiceProvider.GetRequiredService<InventoryDbContext>();var finalCredit=final.ServiceProvider.GetRequiredService<CreditDbContext>();var finalHold=await finalInv.Reservations.SingleAsync(v=>v.OrderId==id);Assert.Equal(2,finalHold.ContractVersion);Assert.Equal(Shop.SharedKernel.StockReservationState.Allocated,finalHold.State);Assert.Equal(deadline,finalHold.ExpiresAt);var finalStock=await finalInv.Stock.SingleAsync(v=>v.VariantId==s.Variant);Assert.Equal(ordinary?3:2,finalStock.OnHand);Assert.Equal(ordinary?3:2,finalStock.Reserved);Assert.Equal(0,finalStock.SourcingReserved);Assert.Equal("Consumed",(await finalSales.SourcingPriceAgreements.SingleAsync(a=>a.AcceptanceId==s.Acceptance)).State);Assert.Equal("Transferred",(await finalInv.SourcingAllocations.SingleAsync(a=>a.AcceptanceId==s.Acceptance)).State);Assert.Single(await finalCredit.PurchaseScopeUses.Where(u=>u.OrderId==id).ToArrayAsync());Assert.Equal(0,await finalSales.OrderCashPayments.CountAsync());Assert.Equal(3,await finalCredit.ClearanceCommands.CountAsync());Assert.Equal(0,await finalSales.Orders.CountAsync(o=>o.State==OrderState.Paid));
    }
